'use strict';
(()=>{const updates=[{"version":"3.6.5","date":"2026-11-20","category":"Improvements","title":"Browse all tools together","intro":"Resources & tools now includes an All tools tab above its categories.","points":["All tools shows resource cards across every category in the current team and is the default browsing view. Category tabs remain available to narrow the list.","Search and the existing access and archive rules still apply. Opening a specific resource shortcut continues to select its category."],"how":"Open a team → Resources & tools → All tools. Choose a category to narrow the list, or return to All tools to browse across categories."},{"version":"3.6.4","date":"2026-11-20","category":"Fixes","title":"Manage resources and permissions directly in team admin","intro":"The team admin resource section now contains the management controls instead of relying on shortcuts.","points":["Resources & permissions lists all team tools with search and Active, restricted, archived and all-resource filters. Admins can add a resource or edit its details and links directly in the admin section.","Restricted resources have a Manage permissions action that opens the member choices and Save resource access controls immediately. Other tools have Configure permissions to enable individual access first.","Fixed resource shortcuts opening the first category rather than the category containing the selected resource. Team-admin and external-service access rules are unchanged."],"how":"Open a team → Team admin → Resources & permissions. Choose Edit resource to change links or details. For restricted resources choose Manage permissions, select the people and Save resource access. Use Configure permissions to restrict a currently shared resource."},{"version":"3.6.3","date":"2026-11-20","category":"Fixes","title":"Edit spreadsheet links directly from their cards","intro":"Admins can edit spreadsheet destinations added directly to the portal, including the HR spreadsheet.","points":["Restored edit controls for directly added spreadsheet cards. Team admins can change the title, description and secure URL without creating a duplicate link.","The inline editor has Save spreadsheet and Cancel actions, preserves specific tab/cell destinations, and reports failed saves. Existing team permissions still control updates.","Resource-library spreadsheet entries keep their existing Edit this destination control."],"how":"Open HR → Spreadsheets → Edit spreadsheet. Change the title, description or URL, then choose Save spreadsheet. Cancel closes the editor without saving."},{"version":"3.6.2","date":"2026-11-20","category":"Improvements","title":"A distinct admin directory with All people","intro":"Administration now opens a searchable people directory instead of another set of Home-style tiles.","points":["Admin settings opens All people by default, showing everyone registered, including archived profiles. Search by name, email or team and filter by active, archived or other access status.","A navy directory sidebar provides All people, individual teams, Awaiting assignment and Archived co-ops with counts. Admin management uses a list workspace instead of the square Home tiles.","Open any person to manage their contact profile, placement, permissions and existing account controls. Returning to Registered people preserves the selected directory group."],"how":"Open Admin settings to see All people. Use the left sidebar for a team or archive view, or use Find a person and Status to narrow the list."},{"version":"3.6.1","date":"2026-11-20","category":"Fixes","title":"Admins can view and edit co-op contact profiles","intro":"The profile fields are now available in person administration as well as My profile.","points":["Portal admins can open a person under Admin settings and choose View / edit contact profile. Team admins can use the same control under Team admin → People & area access for members of their teams.","The editor shows name, phone, contact email, location, LinkedIn, school/program, supervisor, school contact and work schedule. Save contact profile stores changes for that person.","Contact editing is checked on the server and does not grant permission to change roles, placement dates, passwords or sign-in email. Ordinary members and team leads cannot use the admin save action."],"how":"Open Admin settings → a team → a person → View / edit contact profile, or Team admin → People & area access → expand a person → View / edit contact profile. Edit the fields and choose Save contact profile."},{"version":"3.6.0","date":"2026-11-20","category":"Improvements","title":"Complete co-op profiles and clearer resource cards","intro":"Keep contact and school details in My profile, and browse tools and spreadsheets as compact cards.","points":["My profile now includes phone, contact email, city, LinkedIn, school, program, school co-op contact and work days/hours. Sign-in email remains a separate account setting.","Team assignments and placement dates are shown as admin-managed information. Contact details are stored privately in Supabase, visible only to the account owner and authorised portal or team admins.","Resources & tools now uses compact cards with resource status, location and an explicit View resource action. Expand a card for its links and instructions. Spreadsheets uses a separate card grid with clear tab destinations. These working cards are visually distinct from the square Home tiles."],"how":"Open the settings icon → My profile, fill in Contact & placement information and choose Save profile. In a team, open Resources & tools or Spreadsheets to browse the new cards. Ask a team admin to correct placement dates or team membership."},{"version":"3.5.0","date":"2026-11-19","category":"Improvements","title":"Simpler training, clear resources and useful team administration","intro":"Training stays on one page, resources have their own tab, and team admins can manage access and monitor every lesson.","points":["Resources & tools is now a separate team tab and tile. Training, meetings, tasks and spreadsheets keep their own top-level sections; opening a lesson expands it inline without changing pages or fetching its data again.","Training loads its team data in one request and reuses it in memory for that signed-in user for up to a minute. Refresh and saved changes reload it. Lesson and section browsing use the already-loaded data.","Full training is the default for everyone with training access. Team admins can change an individual to Condensed in Team admin → Training versions & completion. Existing completed progress is retained.","The first training section is open. Each next section requires at least 70% completion of the preceding section in that person’s training path. Pending admin confirmation does not count. The server blocks direct access to locked lessons and their links.","Only team admins see completion rates. Their team view shows each person’s total completed, percentage, completed and outstanding lesson lists, learning notes and pending review actions. Co-ops see their individual lesson status without a completion-rate dashboard.","Section names now use normal case and describe the training topics. Admins have clear Add a lesson, Edit this lesson, Edit section names and order, Add a tool and archive/restore controls. The confusing Uploaded documents tab has been removed.","Video and document resources use normal clickable links with clear navy styling. Videos open in a separate browser tab. External providers still control sign-in, sharing and whether a historical recording remains available.","Team admin now has a settings sidebar for people and area access, training versions and completion, resource permissions, spreadsheet destinations, meetings and assignments. Team admins can save area access for existing non-admin members of their own team; portal-wide role and membership changes remain in Portal admin.","Spreadsheets includes the team’s existing resource links to specific Google Sheets tabs, including the original Coop Tasks to do workbook. Tab destinations were checked against its Drive metadata. Historical and access notes are retained, and admins can add a full tab/cell URL.","Existing access was preserved. Resources uses the existing Training & resources permission and individual restricted-tool grants; no new resource permission was granted to everyone."],"how":"Open Training and expand a lesson in place. Choose Resources & tools for working links. Team admins: open Team admin → People & area access to save permissions, or Training versions & completion to choose a person, change their path and inspect completed/outstanding lessons. Use Add a lesson or Edit this lesson to maintain training. Complete 70% of each section to unlock the next."},{"version":"3.4.1","date":"2026-11-19","category":"Fixes","title":"Lesson unlock controls load correctly","intro":"Fixed the admin prerequisite controls on individual learning pages.","points":["Lesson pages now load their existing unlock requirements before displaying the admin controls. This removes an error below the lesson editor and keeps saved prerequisites visible."],"how":"Refresh the portal, open a lesson in Training & tools and expand Training unlock settings."},{"version":"3.4.0","date":"2026-11-19","category":"Features","title":"Team learning paths, resources and section addresses","intro":"Onboarding now lives inside the portal, with editable learning paths and private resources for each team.","points":["Imported 413 training activities and 183 resource-directory entries across HR, Testing, Data, Marketing and Sales. The workbook’s sections, instructions, requirements, source locations and historical or access notes are preserved. Old personal Done marks were not imported.","Training & tools separates Learning paths, Assigned to me, Team resources and Uploaded documents. Team admins also have Team progress with learning notes and review controls. Sections and search keep the library manageable.","Supervisors can assign Full or Condensed training to selected people with a due date and placement warnings. Condensed initially contains the workbook’s core and first-week lessons. Admins choose which lessons belong in each path. Assignments preserve completed progress; path edits apply when assigned again.","Team admins can add or edit lessons and tools, change instructions and resource links, adjust path membership and archive items. Archives retain progress records. Updated lessons are labelled when their revision differs from a past completion.","Learning completion requires a short explanation of what was learned. Lessons that require supervisor confirmation wait for a different team admin to approve them. Access prerequisites can be configured on individual lessons and only unlock portal areas already assigned to that person.","Sensitive tools can require individual portal access. Other people’s learning notes are admin-only. Internal training instructions and resource links are stored in Supabase rather than the public website files. Existing external documents and recordings remain in their original services and keep their own sharing permissions.","Choose a predefined task or training activity inside the task/project assignment form to fill its title and instructions. The assignment keeps a link back to its resources; supervisors still choose assignees, deadlines and recurrence. No task was automatically assigned from the workbook.","Every portal section now has an address such as #/testing/training or #/hr/tasks?view=calendar. Bookmarks, reloads and browser Back/Forward restore the appropriate section after sign-in, while existing team and interview permissions still apply.","Gerrie’s contextual training walkthrough explains paths, practice, completion notes, admin confirmation, resource access, unlocks and updated lessons. Contact-information and meeting-sheet links use the portal’s Profile and Meetings pages."],"how":"Open your team, then Training & tools. Admins can use Assign full or condensed training, open a lesson to edit its path membership or instructions, or choose Add a lesson / Add a tool. Use Team resources for links and access notes. For reusable work, open Tasks & projects, expand Assign a task or project and choose a predefined activity. Copy the current section address to bookmark or share it."},{"version":"3.3.0","date":"2026-11-19","category":"Improvements","title":"Clearer daily work, flexible schedules and private submissions","intro":"See the task that is due now, browse upcoming work in a calendar and keep completion details private.","points":["My work is the default for everyone. Recurring work appears once for its current scheduled occurrence; completed occurrences move to grouped work history. Repeated assignment saves reuse the same record, and task notifications are limited to one per occurrence.","Everyone can choose Team overview to see assignment names, descriptions and due dates. Other people’s completion comments, progress details and submitted files are available only to team admins. Team leads keep assignment management access.","A deadline badge beside each assignment says Due today, Due tomorrow, Due in a number of days, or overdue. Calendar shows future scheduled task occurrences and project due dates.","Tasks support daily, weekly, every two weeks, monthly and every three months. Supervisors choose weekdays explicitly, and monthly or quarterly schedules also require selected weeks of the month. No weekday is chosen automatically. Biweekly schedules follow the week of the First task date.","A required What did you complete? field must be filled before completing an occurrence or uploading a project. Comments and server-recorded timestamps remain in history.","Assigned people can upload completed projects up to 20 MB, including ZIP files. Only team admins can download completed files or completion reports, and another team admin must review an admin’s own submission.","Saturday and Sunday meeting pages are empty, including the training room. Weekday cancellation and timed-access controls are retained.","Existing closed tasks and their history have been retained. Earlier weekly assignments without selected days keep their original weekly completion period. Changing a schedule after work has started requires a new assignment."],"how":"Open Tasks & projects. Start in My work, switch to Team overview or choose Calendar under View. To assign recurring work, select Task, a repeat interval, weekdays and any required month weeks. Add a completion comment before finishing. Team admins can view completion comments, review uploads and download reports from Team overview."},{"version":"3.2.1","date":"2026-11-19","category":"Fixes","title":"Meetings opens with the correct access","intro":"Team meeting tiles now recognise the meeting access assigned to your account.","points":["Fixed an access-summary omission that could incorrectly label Meetings as training required. Existing team permissions and required-training rules still apply."],"how":"Refresh the portal, open your team and choose Meetings."},{"version":"3.2.0","date":"2026-11-19","category":"Features","title":"Placements, daily work and team meetings","intro":"Manage co-op access, assign recurring work and find your team’s meetings, with small reminders from Gerrie.","points":["Gerrie’s notification bell sits beside Settings. It shows assignments, due dates, review feedback, required training, approaching placement ends and upcoming meetings while the portal is open. Read and dismissed state is saved per person.","Admin settings opens team blocks instead of one long list of people. People show their access status and placement end date, with a separate Archived co-ops area.","Portal admins can set co-op start/end dates or full-time status. Co-op access stays active through the end date’s final minute in Toronto time. Expiry blocks workspace access but keeps profiles, interviews and work history. Extending dates restores date-based access; a manual suspension remains separate.","One-off Projects and daily/weekly Tasks support multiple assignees. Recurring tasks use working days and stop at each co-op’s placement end. Supervisors see warnings before assigning deadlines on or after placement ends, or when dates are missing.","My work shows current assignments and recorded completion history. Supervisors can use Team overview, filter by person and review project submissions. Assignment, start, submission and completion timestamps are saved on the server.","Each team has Meetings with Toronto start/end times, Required or Optional labels and Microsoft Teams join buttons. Regular meetings are cancelled on weekends. The daily co-op meeting is optional for Testing.","Team admins can cancel a selected date or suspend a recurring meeting in the portal. These controls do not cancel the underlying Teams event. Join buttons recheck the current schedule when clicked.","The training room needs an explicit timed team or individual access rule. Individual rules can override team access, and no join button is enabled outside the approved window. Meeting URLs remain on the server.","Changelog tiles are only on the main team chooser. The top Changelog button remains available throughout the portal; team dashboards no longer repeat the tile.","Existing co-op dates have not been invented. Enter the real placement dates in person settings before relying on automatic expiry. No training materials or training completions were fabricated."],"how":"Portal admins: open Admin settings, choose a team or Archived co-ops, open a person and Save placement. Supervisors: open Tasks & projects to assign work or review history. Open Meetings to join, cancel a date or configure Training room access. Click Gerrie’s bell for current notifications."},{"version":"3.1.0","date":"2026-11-19","category":"Improvements","title":"A simpler Home and stronger team controls","intro":"Home opens the right workspace, with compact square tiles, clearer navigation and more useful administrator controls.","points":["People with one team go straight to that team’s dashboard. People with secondary teams see the team chooser. Home replaces the Dashboard label, and HR uses Back to HR and Interview overview.","Tiles are smaller squares with consistent line icons. Changelog is available from Home and each team dashboard. Team admins have a management tile inside their team.","Team admin automatically selects every area and includes team lead abilities. Select all areas is also available for each team.","The new Team lead role can create, assign and review team projects. It does not grant interview administration or permission management. Leads still need to complete required project training.","Portal administrator controls have clearer spacing. Active people’s profiles include Act as this person for portal-admin support sessions.","Project reviewers cannot approve their own submissions; another team lead or administrator must review them."],"how":"Open Home to reach your team or team chooser. Portal admins open Admin settings → a person to set a primary team, secondary teams, Team admin or Team lead, and area access, then Save team access. Use the Team admin tile inside a team for its management shortcuts."},{"version":"3.0.2","date":"2026-11-19","category":"Fixes","title":"Clear navigation inside HR","intro":"The interview workspace keeps its navigation compact beside the new portal.","points":["The Dashboard / HR / Interviews breadcrumb stays on a single line when space allows.","Interview home uses a shorter sidebar label, and Help, Changelog and Refresh sit below the interview navigation."],"how":"Open HR → Interviews. Use the breadcrumb for team navigation or the sidebar for interview tasks."},{"version":"3.0.1","date":"2026-11-19","category":"Fixes","title":"Refresh your team dashboard","intro":"New team assignments appear when you refresh the workspace.","points":["Refresh reloads your team memberships and area permissions, then redraws the current portal page.","The dashboard updates its tiles immediately after a membership change, without requiring a full page reload.","Global impersonation activity is restricted to portal admins. Archived team resources are hidden from members."],"how":"After an administrator changes your team or area access, choose Refresh. Your dashboard and team tools will reflect the saved assignments."},{"version":"3.0.0","date":"2026-11-19","category":"Features","title":"Your co-op team workspace","intro":"A new dashboard brings teams, private training, projects and HR tools together through large square tiles.","points":["Open your primary or secondary team, then choose its assigned Training, Projects, Spreadsheets or HR Interviews tiles. The Guhuza name returns to the main dashboard.","Portal admins assign primary teams, secondary teams, team administrators and per-person area access from Admin settings. A team membership alone does not grant Interviews.","Existing accounts retain their HR interview access during the transition. New accounts wait for a team assignment. Existing administrators become portal admins and HR team admins.","Training documents and completed project files are stored privately in Supabase. Spreadsheet URLs are stored on the server and are only returned to authorised accounts. Google still controls access to each sheet.","Team admins can add training resources, create projects, close or reopen projects and review submitted work. Students upload completed files and see review feedback.","Training documents can be required before assigned areas unlock. All required documents must be marked complete; training never grants an unassigned area. Gerrie introduces newly available areas, with the full existing walkthrough for Interviews.","No training content or requirements have been invented. Add the real materials, then configure unlock requirements. Marking training complete records acknowledgement, not verified understanding."],"how":"Start at Dashboard, open a team and choose an area. Portal admins use Admin settings → a person → Primary team, secondary teams, area checkboxes and Save team access. Team admins add resources in Training and work in Projects. Use Training unlock settings on each training document to configure prerequisites."},{"version":"2.4.2","date":"2026-11-18","category":"Improvements","title":"More room for follow-up work","intro":"The follow-up tracker now has two wider status sections.","points":["In progress includes every interview with outstanding tasks, including interviews with no completed tasks yet.","Complete contains interviews with all three follow-up tasks finished.","The Show filter stays within the tracker controls, with stacked search and filter fields on narrow screens.","The separate Not started section and filter have been removed. Saved Not started filters now reopen as In progress."],"how":"Open Follow-up tracker and group by Task status. Work through In progress; interviews move to Complete once all three tasks are checked."},{"version":"2.4.1","date":"2026-11-18","category":"Features","title":"Follow your candidates through recruitment","intro":"Interviewers can see the recruitment stage recorded by admins directly in My interviews.","points":["Admins can mark confirmed submissions to employers, employer interviews, offers and hires, with actual dates and an explicit Save recruitment progress button.","Recruitment progress opens with the saved interview for admins. The highest confirmed stage appears beside the candidate’s name in recent interviews and job folders.","No progress recorded means no active milestone has been saved. Removing or correcting a milestone updates the displayed stage.","People can read recruitment progress for their own interviews. Stage changes remain restricted to active admins."],"how":"Admins: open a candidate from Recruitment funnel or any Admin interview list, update Recruitment progress and save. Interviewers: open My interviews or a job folder to see each candidate’s stage beside their name. Use Refresh to fetch updates made in another session."},{"version":"2.4.0","date":"2026-11-18","category":"Features","title":"Turn team activity into useful insights","intro":"Admin now has focused analytics views with date ranges, filters and graphs you can open to see the underlying interviews.","points":["Interview activity shows daily or weekly volume, the previous matching period and activity by weekday. Team performance adds interviewer counts, a leaderboard and individual trends through filtering.","Jobs & candidate fit shows job coverage and stacked saved-fit assessments, with assessed and Still assessing counts shown separately.","Follow-up progress shows completion rate, outstanding tasks by job or interviewer, aging work and reliable time-to-completion measurements.","Recruitment funnel shows confirmed submissions, employer interviews, offers and hires. Admins record each milestone and its actual date from the saved interview.","Use 7, 14, 30 or custom dates, filter by job and interviewer, and select a graph bar or segment to open its interview records.","Completion timing starts with newly saved interviews. Older records without reliable timestamps are excluded from durations, and recruitment outcomes are never guessed."],"how":"Open Admin and choose a tab under Analytics. Adjust the date and filters, then select a graph to view its records. To update recruitment milestones, open a saved interview and expand Recruitment progress · Admin."},{"version":"2.3.3","date":"2026-11-18","category":"Improvements","title":"A clearer next step for deeper interview questions","intro":"Selected prompts now open as tidy question cards with their takeaway field already visible.","points":["The question picker shows short topic names, with the full prompt displayed after selection.","The optional short takeaway is always open, clearly labelled and focused when a new question is selected.","You can leave the takeaway blank to keep See recording, or remove the question if it was selected by mistake."],"how":"In New interview, open Deeper interview questions and choose a topic. Read the full prompt on its card and enter a brief takeaway directly below it if helpful."},{"version":"2.3.2","date":"2026-11-18","category":"Fixes","title":"Refresh without losing your place","intro":"Reloading now returns you to the workspace page you were using instead of always opening Home.","points":["The current page is remembered separately for each signed-in account and browser tab.","A selected interview reopens only if it is still available to your account.","Admin sections, selected jobs, browsing filters and follow-up filters are restored where available.","This remembers navigation, not unsaved interview drafts or imported notes. Save your work before reloading."],"how":"Refresh normally while working. The site restores your location after sign-in and data loading. If a record is gone or your permissions have changed, it falls back to an accessible page."},{"version":"2.3.1","date":"2026-11-18","category":"Improvements","title":"See fit assessments while browsing interviews","intro":"Admins can see the saved assessment before opening a candidate’s full notes.","points":["Fit labels appear in All interviews and in the interview lists opened through By job or By interviewer.","Labels reflect the existing assessment: Good fit, Possible fit, I have concerns, Not a strong fit or Still assessing.","An interview without a saved fit choice displays Still assessing. This update does not make a new assessment automatically."],"how":"Open Admin, then choose All interviews or open a job or interviewer. Read the fit badge beside each candidate, and open the record when you need the supporting notes."},
{version:'2.3.0',date:'2026-11-18',category:'Features',title:'Meet Gerrie, and find your interviews your way',intro:'A more helpful walkthrough, a browse-first interview library and a clearer follow-up routine.',points:['Gerrie now guides the in-depth tutorial, explaining what each section is for, what to ask and how saving works.','My interviews opens a candidate list. Browse recent interviews, search or choose a job before opening a record.','The follow-up tracker groups work by task status or job, with period filters and sorting.','The AI wording window has a clear X that closes it without applying a suggestion.','Changelog keeps new features, improvements and fixes together, with a complete version history.'],how:'Start with Help & walkthrough for Gerrie’s guide. Use My interviews to choose a candidate, or open Follow-up tracker to organise your next steps.'},
{version:'2.2.1',date:'2026-11-18',category:'Fixes',title:'Team rankings float above the page',intro:'Opening a ranking should help you read it, not rearrange the overview.',points:['Admin’s top-three lists now float above the totals cards without expanding them or moving the grid.','Only one ranking stays open at a time, and its position stays inside the screen.','Your activity on Home now shows only your own totals. Team competition stays in the separate weekly top-five list.'],how:'Hover, focus or tap an Admin period card to open the top three. Click elsewhere or press Escape to close it.'},
{version:'2.2.0',date:'2026-11-18',category:'Features',title:'A working session for admin support',intro:'Admins can work as an active user while keeping their own sign-in separate.',points:['Act as this person starts a full working session using that person’s workspace permissions.','A persistent banner shows whose workspace is open and provides Exit impersonation.','Admin activity records the initiating admin and the workspace records changed during the session.','Working sessions have a time limit and do not replace the admin’s remembered sign-in.'],how:'Admins can open a person’s profile under People & access, expand Permissions and choose Act as this person. Finish saving before exiting.'},
{version:'2.1.0',date:'2026-11-18',category:'Improvements',title:'A focused Admin hub and a little friendly competition',intro:'Team-wide information now has a clear home, while personal activity stays personal.',points:['Admin opens to an overview with separate areas for all interviews, jobs, interviewers, people and admin activity.','Daily interview charts offer 7, 14 and 30 day views, compared with the preceding matching period.','Home activity is ordered Today, This week, This month and All time. Yearly totals remain in Admin.','The weekly top five awards a star to first place and silver and bronze trophies to second and third.','Profiles open Interview totals and Permissions automatically. Interviews and other sections stay collapsed.','Admins can click an interviewer’s name in saved notes to open their profile.'],how:'Use the left-hand Admin menu for detailed work. The chart’s arrows show more or fewer interviews than the preceding period; the selected range includes today.'},
{version:'2.0.0',date:'2026-11-18',category:'Improvements',title:'A calmer place to start your day',intro:'The homepage was redesigned around the work co-op students actually need to do.',points:['A single Start an interview action leads the page.','A simpler sidebar uses clearer labels: New interview, My interviews and Follow-up tracker.','Personal activity, recent interviews and beginner guidance each have their own space.','Guhuza navy colours, responsive layouts and gentle hover movement create a consistent interface. Reduced-motion preferences are respected.'],how:'Click the Guhuza name to return Home from anywhere. Use the sidebar to move between your interview tasks.'},
{version:'1.3.0',date:'2026-11-18',category:'Features',title:'Bring your backlog and manage your team',intro:'Old interview notes can become searchable records, and admins can manage people without losing their history.',points:['Every active user can paste supported interview notes or upload TXT, Markdown, HTML and DOCX files.','Imports are previewed before saving and require the original interview date. Exact repeat imports are skipped.','Admins can assign old interviews to the correct registered interviewer.','People profiles show interview totals, jobs and saved interviews, with an explicit Save permissions button.','Remove access retains a profile and interview history and can be reversed. Permanent workspace profile deletion is a separate action.'],how:'Open Import interviews, review the preview and original dates, then import the selected records. For departing team members, admins will usually want Remove access.'},
{version:'1.2.0',date:'2026-11-16',category:'Improvements',title:'Navy branding and a more organised form',intro:'The interview form gained a clearer structure and Guhuza’s navy colours.',points:['Section links help you move between candidate details, commute, preferences, next steps and optional questions.','Sections have clearer headings, spacing and helpful explanations.','The form adapts to smaller screens, with larger controls for entering answers.'],how:'Work from top to bottom or use the section links to jump to a question during the conversation. Save before leaving the draft.'},
{version:'1.1.1',date:'2026-11-16',category:'Fixes',title:'Clearer sign-in recovery and account navigation',intro:'A loading problem should not automatically erase a valid saved sign-in.',points:['Session-loading errors have a retry path and retain the saved sign-in.','The account menu brings profile, settings and sign-out together in the top-right corner.','The Guhuza name provides a direct route back Home.'],how:'If loading fails, use the retry action. Use the account menu for profile and sign-in settings, and sign out on a shared computer.'},
{version:'1.1.0',date:'2026-11-16',category:'Features',title:'Your own dashboard, profile and settings',intro:'Personal activity and account tools were added alongside guided onboarding.',points:['Home summarises interviews belonging to the signed-in person.','Profile shows account details and interview totals and allows a display-name update.','Settings provides password-reset and email-change requests.','An interactive walkthrough introduces the interview workflow.'],how:'Open the top-right account menu for My profile or Settings. Use Help & walkthrough whenever you need a refresher.'},
{version:'1.0.0',date:'2026-11-16',category:'Features',title:'The shared interview workspace begins',intro:'The first published workspace brought interview notes, accounts and follow-up into one place.',points:['Users can register and sign in with a password.','The interview form captures candidate answers and fills in the signed-in interviewer.','Saved interview records keep table and plain-text notes together.','Shared jobs can be found by title or job ID, and follow-up tasks stay attached to the interview.','Admin access separates team management from ordinary account permissions.'],how:'Sign in, start a real interview and save it. Your saved records remain available in the workspace for review and follow-up.'}
];const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};let category='All updates';const compare=(a,b)=>{const aa=a.version.split('.').map(Number),bb=b.version.split('.').map(Number);return aa[0]-bb[0]||aa[1]-bb[1]||aa[2]-bb[2];};const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'});
function open(post){const root=$('changelogFeed');root.replaceChildren();$('changelogControls').hidden=true;const back=el('button','← All updates','admin-back');back.onclick=render;const article=el('article',undefined,'change-article'),meta=el('div',undefined,'change-meta');meta.append(el('span','v'+post.version,'change-version'),el('span',post.category,'change-category'),el('time',date(post.date)));article.append(meta,el('h2',post.title),el('p',post.intro,'change-intro'));const list=el('ul');for(const point of post.points)list.append(el('li',point));article.append(el('h3','What changed'),list,el('h3','How to use it'),el('p',post.how));root.append(back,article);window.scrollTo({top:0,behavior:'smooth'});}
function render(){$('changelogControls').hidden=false;for(const b of document.querySelectorAll('[data-change-category]'))b.setAttribute('aria-pressed',String(b.dataset.changeCategory===category));const rows=updates.filter(p=>category==='All updates'||p.category===category).sort(compare);if($('changelogSort').value==='newest')rows.reverse();const root=$('changelogFeed');root.replaceChildren();for(const post of rows){const card=el('article',undefined,'change-card'),meta=el('div',undefined,'change-meta');meta.append(el('span','v'+post.version,'change-version'),el('span',post.category,'change-category '+post.category.toLowerCase()),el('time',date(post.date)));const title=el('button',post.title,'change-title');title.onclick=()=>open(post);card.append(meta,title,el('p',post.intro));const points=el('ul');for(const point of post.points.slice(0,2))points.append(el('li',point));const read=el('button','Read update →','change-read');read.onclick=()=>open(post);card.append(points,read);root.append(card);}}
function start(){const section=el('section');section.id='changelogPanel';section.hidden=true;section.innerHTML='<div class="changes-heading"><div><p class="eyebrow">GUHUZA WORKSPACE UPDATES</p><h1>Small changes.<br>A better workday.</h1><p>New tools, thoughtful improvements and the fixes that make your interviews easier.</p><span class="current-version">Current version · v'+updates[0].version+'</span></div><img src="gerrie-guide.png" alt="Gerrie welcomes you to the update history"></div><div id="changelogControls"><div class="change-filters" role="group" aria-label="Filter website updates"><button data-change-category="All updates">All updates</button><button data-change-category="Features">New features</button><button data-change-category="Improvements">Improvements</button><button data-change-category="Fixes">Fixes</button></div><label class="changes-sort">History order<select id="changelogSort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label></div><p class="history-note">Version labels were introduced with this changelog. Earlier published changes have been grouped into retrospective releases using the repository history.</p><div id="changelogFeed"></div>';$('workspace').append(section);const button=el('button','Changelog');button.id='changelogTab';button.type='button';$('refreshData').before(button);button.onclick=()=>{GuhuzaUI.show('changelog');render();};document.querySelectorAll('[data-change-category]').forEach(b=>b.onclick=()=>{category=b.dataset.changeCategory;render();});$('changelogSort').onchange=render;}
window.GuhuzaChanges={start,render,updates};})();
